```javascript
function writeCombinedCounts() {
  var ss = SpreadsheetApp.openById("1aFB2O37w-Dh0RmN_W2CultjS1X4Vb7LqxbKMb99UVp4");
  var sheet = ss.getSheetByName("シート名またはgid=2119386543のシート");
  // ※ gid 2119386543 のシートを取得する場合は ss.getSheets() から sheetId が一致するものを探します
  var sheets = ss.getSheets();
  var targetSheet = null;
  for (var i = 0; i < sheets.length; i++) {
    if (sheets[i].getSheetId() == 2119386543) {
      targetSheet = sheets[i];
      break;
    }
  }
  if (!targetSheet) targetSheet = sheets[0];

  var data = [
    ["月", "キャンセル申告等合計 (A列ベース)", "解約阻止等合計 (N/O列ベース)"],
    ["2026-03", 1599, 225],
    ["2026-04", 594, 165],
    ["2026-05", 445, 157],
    ["2026-06", 414, 177],
    ["2026-07", 698, 284],
    ["2026-08", 1443, 507],
    ["2026-09", 814, 167]
  ];

  targetSheet.getRange(1, 1, data.length, data[0].setValues ? 3 : 3).setValues(data);
}
